data class SshProfile(val name:String,val host:String,val port:Int=22,val user:String,val password:String="",val privateKey:String="",val passphrase:String="",val timeout:Int=15,val keepAlive:Int=15)
class ProfileStore(c:Context){private val p=c.getSharedPreferences("profiles",Context.MODE_PRIVATE);fun load():List<SshProfile>=runCatching{val a=JSONArray(p.getString("items","[]"));(0 until a.length()).map{i->a.getJSONObject(i).let{o->SshProfile(o.getString("name"),o.getString("host"),o.optInt("port",22),o.getString("user"),o.optString("password"),o.optString("privateKey"),o.optString("passphrase"),o.optInt("timeout",15),o.optInt("keepAlive",15))}}}.getOrDefault(emptyList());fun save(x:List<SshProfile>){val a=JSONArray();x.forEach{v->a.put(JSONObject().apply{put("name",v.name);put("host",v.host);put("port",v.port);put("user",v.user);put("password",v.password);put("privateKey",v.privateKey);put("passphrase",v.passphrase);put("timeout",v.timeout);put("keepAlive",v.keepAlive)})};p.edit().putString("items",a.toString()).apply()}}
class HostKeyStore(c:Context){private val p=c.getSharedPreferences("trusted_host_keys",Context.MODE_PRIVATE);fun get(h:String,n:Int)=p.getString("$h:$n",null);fun trust(h:String,n:Int,k:String)=p.edit().putString("$h:$n",k).apply()}
data class HostPrompt(val fingerprint:String,val key:String,val changed:Boolean)
data class PortForward(val local:Int,val remoteHost:String,val remotePort:Int)
@Composable fun FreeSshApp(store:ProfileStore,keys:HostKeyStore){var ps by remember{mutableStateOf(store.load())};var sel by remember{mutableStateOf<SshProfile?>(null)};if(sel!=null)SessionScreen(sel!!,keys){sel=null}else ConnectionScreen(ps,{v->ps=ps+v;store.save(ps)},{sel=it},{v->ps=ps-v;store.save(ps)})}
