onSave(profile())}){Text("Salvar")}};Text("Perfis salvos",style=MaterialTheme.typography.titleLarge,color=AppText)};items(profiles){v->Card{Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(v.name,color=AppText);Text("${v.user}@${v.host}:${v.port}",color=AppMuted)};Button({onConnect(v)}){Text("Abrir")};IconButton({onDelete(v)}){Icon(Icons.Default.Delete,"Excluir",tint=AppText)}}}}}}
private val ansi=Regex("\u001B\\[[0-?]*[ -/]*[@-~]");private val osc=Regex("\u001B\\][^\u0007]*(?:\u0007|$)");private val title=Regex("(?:\u001B)?\\]0;[^\n\r\u001B]*");private val charset=Regex("\u001B[()][A-Za-z0-9]")
private fun clean(raw:String):String{var s=osc.replace(raw,"");s=title.replace(s,"");s=charset.replace(s,"");s=s.replace("\u001B[?2004h","").replace("\u001B[?2004l","");return s.replace(Regex("\\r+\\n"),"\n").replace("\r","")}
private fun styled(raw:String):AnnotatedString{val s=clean(raw);val b=AnnotatedString.Builder();var pos=0;var c=Color(0xFFE6E6E6);ansi.findAll(s).forEach{m->if(m.range.first>pos)b.withStyle(SpanStyle(c)){append(s.substring(pos,m.range.first))};if(m.value.endsWith("m")){val ns=m.value.removePrefix("\u001B[").removeSuffix("m").split(';').mapNotNull{it.toIntOrNull()};if(ns.isEmpty()||0 in ns)c=Color(0xFFE6E6E6);ns.forEach{n->c=when(n){31,91->Color(0xFFFF5F56);32,92->Color(0xFF64E572);33,93->Color(0xFFFFD75F);34,94->Color(0xFF4C9AFF);35,95->Color(0xFFD875FF);36,96->Color(0xFF55DDE0);37,97->Color.White;else->c}}};pos=m.range.last+1};if(pos<s.length)b.withStyle(SpanStyle(c)){append(s.substring(pos))};return b.toAnnotatedString()}
private fun newSession(p:SshProfile):Session{val j=JSch();if(p.privateKey.isNotBlank())j.addIdentity("profile",p.privateKey.toByteArray(),null,p.passphrase.ifBlank{null}?.toByteArray());return j.getSession(p.user,p.host,p.port).apply{if(p.password.isNotBlank())setPassword(p.password);timeout=p.timeout*1000;serverAliveInterval=(p.keepAlive.coerceAtLeast(5))*1000;serverAliveCountMax=3}}
@Composable fun SessionScreen(p:SshProfile,keys:HostKeyStore,onBack:()->Unit){var tab by remember{mutableIntStateOf(0)};var session by remember{mutableStateOf<Session?>(null)};var shell by remember{mutableStateOf<ChannelShell?>(null)};var stdin by remember{mutableStateOf<OutputStream?>(null)};var output by remember{mutableStateOf("")};var connected by remember{mutableStateOf(false)};var reconnecting by remember{mutableStateOf(false)};var prompt by remember{mutableStateOf<HostPrompt?>(null)};var decision by remember{mutableStateOf<Boolean?>(null)};var logs by remember{mutableStateOf(listOf<String>())};var stop by remember{mutableStateOf(false)};var reconnectGeneration by remember{mutableIntStateOf(0)};val lifecycleOwner=LocalLifecycleOwner.current;val fmt=remember{SimpleDateFormat("HH:mm:ss",Locale.getDefault())};fun log(x:String){logs=logs+("${fmt.format(Date())}  $x")};fun close(){stop=true;runCatching{shell?.disconnect()};runCatching{session?.disconnect()}};DisposableEffect(lifecycleOwner){val observer=LifecycleEventObserver{_,event->if(event==Lifecycle.Event.ON_RESUME&&!stop){val s=session;val sh=shell;if(s==null||sh==null||!s.isConnected||!sh.isConnected){runCatching{sh?.disconnect()};runCatching{s?.disconnect()};session=null;shell=null;stdin=null;connected=false;reconnecting=true;reconnectGeneration++}}};lifecycleOwner.lifecycle.addObserver(observer);onDispose{lifecycleOwner.lifecycle.removeObserver(observer)}};if(prompt!=null)AlertDialog(onDismissRequest={decision=false},title={Text(if(prompt!!.changed)"Chave do servidor mudou" else "Confiar neste servidor?")},text={Text("${p.host}:${p.port}\n${prompt!!.fingerprint}",fontFamily=FontFamily.Monospace)},confirmButton={Button({decision=true}){Text("Confiar")}},dismissButton={TextButton({decision=false}){Text("Cancelar")}})
LaunchedEffect(p,reconnectGeneration){stop=false;withContext(Dispatchers.IO){var localSession:Session?=null;var localShell:ChannelShell?=null;try{withContext(Dispatchers.Main){connected=false;reconnecting=reconnectGeneration>0};val s=newSession(p);localSession=s;s.setConfig(Properties().apply{put("StrictHostKeyChecking","ask");put("TCPKeepAlive","yes")});s.setUserInfo(object:UserInfo{override fun getPassword()=p.password;override fun getPassphrase()=p.passphrase;override fun promptPassword(x:String)=p.password.isNotBlank();override fun promptPassphrase(x:String)=p.passphrase.isNotBlank();override fun showMessage(x:String){};override fun promptYesNo(x:String):Boolean{val hk=s.hostKey?:return false;val cur=hk.key;val saved=keys.get(p.host,p.port);if(saved==cur)return true;runOnUiThread{decision=null;prompt=HostPrompt(hk.getFingerPrint(JSch()),cur,saved!=null&&saved!=cur)};while(decision==null&&!stop)Thread.sleep(80);val ok=decision==true;if(ok)keys.trust(p.host,p.port,cur);runOnUiThread{prompt=null};return ok}});s.connect(p.timeout*1000);val sh=s.openChannel("shell") as ChannelShell;localShell=sh;sh.setPty(true);sh.setPtyType("xterm-256color",80,40,800,720);val out=sh.outputStream;val input=sh.inputStream;sh.connect(p.timeout*1000);withContext(Dispatchers.Main){session=s;shell=sh;stdin=out;connected=true;reconnecting=false;log(if(reconnectGeneration==0)"SSH conectado a ${p.host}:${p.port}" else "SSH reconectado")};val buf=ByteArray(8192);while(currentCoroutineContext().isActive&&!stop&&sh.isConnected&&s.isConnected){val n=input.read(buf);if(n<0)break;if(n>0){val x=String(buf,0,n);withContext(Dispatchers.Main){output+=x}}};if(!stop){withContext(Dispatchers.Main){connected=false;reconnecting=true;stdin=null;session=null;shell=null;reconnectGeneration++}}}catch(e:Exception){if(!stop){withContext(Dispatchers.Main){connected=false;reconnecting=true;stdin=null;session=null;shell=null;log("SSH caiu: ${e.message ?: "sem resposta"}")};delay(1500);withContext(Dispatchers.Main){if(!stop)reconnectGeneration++}}}finally{runCatching{localShell?.disconnect()};runCatching{localSession?.disconnect()}}}};DisposableEffect(Unit){onDispose{close()}}
Column(Modifier.fillMaxSize().background(AppBg).statusBarsPadding()){Row(Modifier.fillMaxWidth().background(Color(0xFF0B1821)).padding(12.dp),verticalAlignment=Alignment.CenterVertically){IconButton({close();onBack()}){Icon(Icons.Default.ArrowBack,"Voltar",tint=AppText)};Column(Modifier.weight(1f)){Text(p.name,style=MaterialTheme.typography.titleLarge,color=AppText);Text(when{connected->"●  Conectado";reconnecting->"●  Reconectando...";else->"●  Conectando..."},color=if(connected)Color(0xFF38E65C) else Color(0xFFFFC857))}};Box(Modifier.weight(1f)){when(tab){0->TerminalTab(output,stdin);1->SftpTab(session,connected,{log(it)});2->PortsTab(session,connected,{log(it)});3->LogsTab(logs)}};BottomTabs(tab){tab=it}}}
@Composable fun TerminalTab(output:String,stdin:OutputStream?){var cmd by remember{mutableStateOf("")};val focus=remember{FocusRequester()};val keyboard=LocalSoftwareKeyboardController.current;val clip=LocalClipboardManager.current;val sv=rememberScrollState();val writer=remember{Executors.newSingleThreadExecutor()};fun write(x:String){val w=stdin?:return;writer.execute{runCatching{synchronized(w){w.write(x.toByteArray());w.flush()}}}};fun changed(v:String){when{v.startsWith(cmd)->write(v.substring(cmd.length));cmd.startsWith(v)->repeat(cmd.length-v.length){write("\u007f")};else->{repeat(cmd.length){write("\u007f")};write(v)}};cmd=v};DisposableEffect(Unit){onDispose{writer.shutdownNow()}};LaunchedEffect(output){sv.animateScrollTo(sv.maxValue)};Column(Modifier.fillMaxSize()){Box(Modifier.weight(1f).fillMaxWidth().clickable{focus.requestFocus();keyboard?.show()}){Box(Modifier.fillMaxSize().verticalScroll(sv)){Text(styled(output),fontFamily=FontFamily.Monospace,fontSize=12.sp,lineHeight=13.sp,softWrap=true,modifier=Modifier.fillMaxWidth().padding(10.dp))};BasicTextField(cmd,{changed(it)},Modifier.size(1.dp).focusRequester(focus),textStyle=TextStyle(Color.Transparent,fontSize=1.sp),singleLine=true,keyboardOptions=KeyboardOptions(imeAction=ImeAction.Send),keyboardActions=KeyboardActions(onSend={write("\r");cmd=""},onDone={write("\r");cmd=""}))};Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()).background(Color(0xFF061018)).imePadding().padding(5.dp),horizontalArrangement=Arrangement.spacedBy(5.dp)){fun k(t:String,x:String){TermKey(t){write(x)}};k("ESC","\u001b");k("TAB","\t");k("↑","\u001b[A");k("↓","\u001b[B");k("←","\u001b[D");k("→","\u001b[C");k("HOME","\u001b[H");k("END","\u001b[F");TermKey("CTRL+V"){val x=clip.getText()?.text.orEmpty();if(x.isNotEmpty()){write(x);cmd+=x}};k("CTRL+C","\u0003");k("CTRL+D","\u0004");k("CTRL+Z","\u001a");k("CTRL+L","\u000c")}}}
@Composable fun SftpTab(session:Session?,connected:Boolean,onLog:(String)->Unit){var path by remember{mutableStateOf(".")};var entries by remember{mutableStateOf(listOf<Pair<String,Boolean>>())};var status by remember{mutableStateOf("")};var pendingDownloadRemote by remember{mutableStateOf<String?>(null)};var pendingDownloadName by remember{mutableStateOf("")};val context=LocalContext.current;val scope=rememberCoroutineScope();fun remote(base:String,name:String)=if(base.endsWith('/'))base+name else "$base/$name";fun load(p:String){val s=session;if(!connected||s==null){status="SSH desconectado";return};scope.launch(Dispatchers.IO){runCatching{val c=s.openChannel("sftp") as ChannelSftp;try{c.connect();c.ls(p).map{it as ChannelSftp.LsEntry}.filter{it.filename!="."}.map{it.filename to it.attrs.isDir}}finally{if(c.isConnected)c.disconnect()}}.onSuccess{list->withContext(Dispatchers.Main){entries=list;path=p;status="${list.size} itens";onLog("SFTP listou $p")}}.onFailure{e->withContext(Dispatchers.Main){status="Erro: ${e.message}";onLog("Erro SFTP: ${e.message}")}}}}};val downloadLauncher=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/octet-stream")){uri->val remoteFile=pendingDownloadRemote;val fileName=pendingDownloadName;if(uri!=null&&remoteFile!=null){val s=session;if(!connected||s==null){status="SSH desconectado"}else scope.launch(Dispatchers.IO){runCatching{val c=s.openChannel("sftp") as ChannelSftp;try{c.connect();val expected=c.lstat(remoteFile).size;val copied=context.contentResolver.openOutputStream(uri,"w")?.use{out->c.get(remoteFile).use{input->val n=input.copyTo(out,64*1024);out.flush();n}}?:error("Não foi possível abrir o arquivo local");if(expected>0&&copied<=0)error("Transferência retornou 0 bytes para um arquivo remoto de $expected bytes");Pair(copied,expected)}finally{if(c.isConnected)c.disconnect()}}.onSuccess{(copied,expected)->withContext(Dispatchers.Main){status="Baixado: $fileName (${copied} bytes)";onLog("SFTP download: $remoteFile - $copied/$expected bytes")}}.onFailure{e->withContext(Dispatchers.Main){status="Erro no download: ${e.message}";onLog("Erro SFTP download: ${e.message}")}}}}}};val uploadLauncher=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null){val s=session;if(!connected||s==null){status="SSH desconectado"}else{val name=context.contentResolver.query(uri,arrayOf(OpenableColumns.DISPLAY_NAME),null,null,null)?.use{c->if(c.moveToFirst())c.getString(0)else null}?:uri.lastPathSegment?.substringAfterLast('/')?:"arquivo";val target=remote(path,name);scope.launch(Dispatchers.IO){runCatching{val c=s.openChannel("sftp") as ChannelSftp;try{c.connect();val copied=context.contentResolver.openInputStream(uri)?.use{input->c.put(target).use{out->val n=input.copyTo(out,64*1024);out.flush();n}}?:error("Não foi possível abrir o arquivo selecionado");val remoteSize=c.lstat(target).size;if(copied>0&&remoteSize<=0)error("Servidor gravou 0 bytes após enviar $copied bytes");Pair(copied,remoteSize)}finally{if(c.isConnected)c.disconnect()}}.onSuccess{(copied,remoteSize)->withContext(Dispatchers.Main){status="Enviado: $name (${copied} bytes)";onLog("SFTP upload: $target - $copied/$remoteSize bytes");load(path)}}.onFailure{e->withContext(Dispatchers.Main){status="Erro no envio: ${e.message}";onLog("Erro SFTP upload: ${e.message}")}}}}}}};LaunchedEffect(connected){if(connected)load(path)};Column(Modifier.fillMaxSize().background(AppBg).padding(12.dp)){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text("SFTP",style=MaterialTheme.typography.headlineSmall,color=AppText,modifier=Modifier.weight(1f));IconButton({if(connected)uploadLauncher.launch(arrayOf("*/*"))else status="SSH desconectado"}){Icon(Icons.Default.Add,"Enviar arquivo",tint=AppText)}};Row(verticalAlignment=Alignment.CenterVertically){OutlinedTextField(path,{path=it},label={Text("Caminho remoto",color=AppText)},textStyle=TextStyle(color=AppText),colors=OutlinedTextFieldDefaults.colors(focusedTextColor=AppText,unfocusedTextColor=AppText,focusedLabelColor=AppText,unfocusedLabelColor=AppText,cursorColor=Color(0xFF2D8CFF)),modifier=Modifier.weight(1f));IconButton({load(path)}){Icon(Icons.Default.Refresh,"Atualizar",tint=AppText)}};Text(status,color=AppMuted);LazyColumn{items(entries){e->Row(Modifier.fillMaxWidth().clickable{if(e.second)load(remote(path,e.first))else{pendingDownloadRemote=remote(path,e.first);pendingDownloadName=e.first;downloadLauncher.launch(e.first)}}.padding(vertical=10.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(e.second)Icons.Default.Folder else Icons.Default.InsertDriveFile,null,tint=if(e.second)Color(0xFF4C9AFF) else Color.LightGray);Spacer(Modifier.width(10.dp));Text(e.first,color=AppText)}}}}}
@Composable fun PortsTab(session:Session?,connected:Boolean,onLog:(String)->Unit){var lp by remember{mutableStateOf("8080")};var rh by remember{mutableStateOf("127.0.0.1")};var rp by remember{mutableStateOf("80")};var forwards by remember{mutableStateOf(listOf<PortForward>())};var status by remember{mutableStateOf("")};Column(Modifier.fillMaxSize().background(AppBg).padding(12.dp)){Text("Portas",style=MaterialTheme.typography.headlineSmall,color=AppText);Text("Encaminhamento local SSH",color=AppMuted);OutlinedTextField(lp,{lp=it},label={Text("Porta local")},textStyle=TextStyle(color=AppText),modifier=Modifier.fillMaxWidth());OutlinedTextField(rh,{rh=it},label={Text("Host remoto")},textStyle=TextStyle(color=AppText),modifier=Modifier.fillMaxWidth());OutlinedTextField(rp,{rp=it},label={Text("Porta remota")},textStyle=TextStyle(color=AppText),modifier=Modifier.fillMaxWidth());Button({val s=session;val l=lp.toIntOrNull();val r=rp.toIntOrNull();if(!connected||s==null)status="SSH desconectado" else if(l==null||r==null)status="Portas inválidas" else runCatching{s.setPortForwardingL(l,rh,r);forwards=forwards+PortForward(l,rh,r);status="127.0.0.1:$l → $rh:$r";onLog("Túnel aberto: $status")}.onFailure{status="Erro: ${it.message}"}}){Text("Abrir túnel")};Text(status,color=AppMuted);forwards.forEach{f->Row(Modifier.fillMaxWidth().padding(vertical=6.dp),verticalAlignment=Alignment.CenterVertically){Text("127.0.0.1:${f.local} → ${f.remoteHost}:${f.remotePort}",Modifier.weight(1f),color=AppText);IconButton({runCatching{session?.delPortForwardingL(f.local)};forwards=forwards-f;onLog("Túnel ${f.local} fechado")}){Icon(Icons.Default.Close,"Fechar",tint=AppText)}}}}}
